import { z } from 'zod';
import { WalletHistoryViewType } from '~/entities/wallet/types';

// 날짜 관련 파라미터 (초기화 대상)
const dateSearchSchema = z.object({
  stDt: z.string().optional(), // 초기화 시 설정됨
  edDt: z.string().optional(), // 초기화 시 설정됨
});

// 선택적 파라미터 (페이지별로 다르게 사용)
const optionalSearchSchema = z.object({
  walletDetailSe: z.string().optional(),
  coinType: z.string().optional(),
  walletInsttCd: z.string().optional(),
  aliasNm: z.string().optional(),
  vouchId: z.string().optional(),
  text: z.string().optional(),
  coinId: z.string().optional(),
  viewType: z.nativeEnum(WalletHistoryViewType).optional(),
});

export const walletSearchSchema = dateSearchSchema.merge(optionalSearchSchema);

export type WalletSearchParams = z.infer<typeof walletSearchSchema>;
