import { endOfMonth, format, startOfMonth } from 'date-fns';
import { useCallback } from 'react';
import { useSearchParams } from 'react-router-dom';
import { walletSearchSchema } from '~/entities/wallet/model/search-params';
import { UseWalletSearchParamsReturn } from '~/entities/wallet/types';

export const useWalletSearchParams = (): UseWalletSearchParamsReturn => {
  const [searchParams, setSearchParams] = useSearchParams();

  const getStDt = useCallback((date: Date = new Date()) => {
    return format(startOfMonth(date), 'yyyy-MM-dd');
  }, []);

  const getEdDt = useCallback((date: Date = new Date()) => {
    return format(endOfMonth(date), 'yyyy-MM-dd');
  }, []);

  const updateSearchParams = useCallback(
    (updates: Record<string, string | null>) => {
      requestAnimationFrame(() => {
        setSearchParams(
          (prev) => {
            const newParams = new URLSearchParams(prev);
            Object.entries(updates).forEach(([key, value]) => {
              if (value === null) {
                newParams.delete(key);
              } else {
                newParams.set(key, value);
              }
            });
            return newParams;
          },
          { replace: true },
        );
      });
    },
    [setSearchParams],
  );

  const resetSearchParams = useCallback(() => {
    setSearchParams(new URLSearchParams(), { replace: true });
  }, [setSearchParams]);

  const params = Object.fromEntries(searchParams.entries());
  const parsedParams = walletSearchSchema.parse(params);

  return {
    searchParams: parsedParams,
    updateSearchParams,
    resetSearchParams,
    getStDt,
    getEdDt,
  };
};
